1.query:
fetch logs
| filter service.name == "checkout" and matchesPhrase(content, "Order placed")
| summarize orders = count(), by:{bin(timestamp, 1h)}

2.query:
fetch spans
| filter service.name == "checkout" and span.name == "POST /checkout"
| summarize p95 = percentile(duration, 95), by:{bin(start_time, 1h)}
